import { TestBed } from '@angular/core/testing';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

function tmdbMovie(id: number, title: string): TmdbMovie {
  return {
    id,
    title,
    release_date: '2024-06-01',
    poster_path: null,
    overview: 'Acceptance test fixture',
  };
}

function titlesOf(component: Watchlist): string[] {
  return component.movies().map((item) => item.title);
}

describe('watchlist: unwatched movies before watched ones', () => {
  beforeEach(() => {
    localStorage.clear();
    TestBed.resetTestingModule();
    TestBed.configureTestingModule({ imports: [Watchlist] });
  });

  it('lists unwatched movies before watched movies', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const store = TestBed.inject(WatchlistStore);
    store.add(tmdbMovie(1, 'Unwatched One'));
    store.add(tmdbMovie(2, 'Watched One'));
    store.toggleWatched(2);
    store.add(tmdbMovie(3, 'Unwatched Two'));

    expect(titlesOf(fixture.componentInstance)).toEqual([
      'Unwatched One',
      'Unwatched Two',
      'Watched One',
    ]);
  });

  it('keeps the relative order inside each group', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const store = TestBed.inject(WatchlistStore);
    store.add(tmdbMovie(1, 'A'));
    store.add(tmdbMovie(2, 'B'));
    store.add(tmdbMovie(3, 'C'));
    store.add(tmdbMovie(4, 'D'));
    store.toggleWatched(2);
    store.toggleWatched(4);

    expect(titlesOf(fixture.componentInstance)).toEqual(['A', 'C', 'B', 'D']);
  });

  it('reorders as soon as a movie is toggled from the view', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const store = TestBed.inject(WatchlistStore);
    store.add(tmdbMovie(1, 'A'));
    store.add(tmdbMovie(2, 'B'));
    store.add(tmdbMovie(3, 'C'));

    fixture.componentInstance.toggleWatched(2);

    expect(titlesOf(fixture.componentInstance)).toEqual(['A', 'C', 'B']);
  });

  it('renders unwatched movies before watched ones in the template', () => {
    const fixture = TestBed.createComponent(Watchlist);
    const store = TestBed.inject(WatchlistStore);
    store.add(tmdbMovie(11, 'Kaiju Unwatched'));
    store.add(tmdbMovie(12, 'Robot Watched'));
    store.toggleWatched(12);

    fixture.detectChanges();

    const html = (fixture.nativeElement as HTMLElement).innerHTML;
    const unwatchedAt = html.indexOf('Kaiju Unwatched');
    const watchedAt = html.indexOf('Robot Watched');
    expect(unwatchedAt).toBeGreaterThanOrEqual(0);
    expect(watchedAt).toBeGreaterThan(unwatchedAt);
  });
});
```

